export default {"html":"<p data-line=\"0\" class=\"code-line\">Since iOS 16, the Settings app design updated so content sections have margins on the left and right as well as top and bottom.</p>\n<p data-line=\"2\" class=\"code-line\"><img src=\"/images/5325127b665d56/appledesign15.jpg\" alt=\"appledesign15.jpg\" class=\"md-img\" loading=\"lazy\"></p>\n<p data-line=\"4\" class=\"code-line\">Ionic added an <code>inset</code> property on <code>ion-list</code>, so <code>&lt;ion-list inset=true&gt;</code> brings layouts closer to iOS 16 and later. It is opt-in rather than a default change so existing designs do not break.</p>\n<p data-line=\"6\" class=\"code-line\">Side by side, it looks like this (<code>color=light</code> on <code>ion-toolbar</code> and <code>ion-content</code>).</p>\n<p data-line=\"8\" class=\"code-line\"><img src=\"/images/5325127b665d56/inset.png\" alt=\"inset.png\" class=\"md-img\" loading=\"lazy\"></p>\n<p data-line=\"10\" class=\"code-line\">That works for this content, but to recreate iOS Settings you need icons on each row. Screens like \"Payment &amp; Shipping\" also need list titles and item notes. Let's meet those requirements while keeping Ionic's base components.</p>\n<h2 id=\"step-1%3A-set-up-the-html\" data-line=\"12\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#step-1%3A-set-up-the-html\" aria-hidden=\"true\"></a> Step 1: Set up the HTML</h2>\n<p data-line=\"14\" class=\"code-line\">This is code extracted from a real product. Compared with the default pattern, the main change is adding <code>ion-item-group</code>. Icons follow the documented approach.</p>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"16\"><span class=\"line\"><span style=\"color:#E1E4E8\">&lt;</span><span style=\"color:#85E89D\">ion-header</span><span style=\"color:#B392F0\"> [translucent]</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"true\"</span><span style=\"color:#E1E4E8\">&gt;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  &lt;</span><span style=\"color:#85E89D\">ion-toolbar</span><span style=\"color:#B392F0\"> color</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"light\"</span><span style=\"color:#E1E4E8\">&gt;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    &lt;</span><span style=\"color:#85E89D\">ion-title</span><span style=\"color:#E1E4E8\">&gt;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">      Settings</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    &lt;/</span><span style=\"color:#85E89D\">ion-title</span><span style=\"color:#E1E4E8\">&gt;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  &lt;/</span><span style=\"color:#85E89D\">ion-toolbar</span><span style=\"color:#E1E4E8\">&gt;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">&lt;/</span><span style=\"color:#85E89D\">ion-header</span><span style=\"color:#E1E4E8\">&gt;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">&lt;</span><span style=\"color:#85E89D\">ion-content</span><span style=\"color:#B392F0\"> color</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"light\"</span><span style=\"color:#B392F0\"> [fullscreen]</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"true\"</span><span style=\"color:#E1E4E8\">&gt;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  &lt;</span><span style=\"color:#85E89D\">ion-header</span><span style=\"color:#B392F0\"> collapse</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"condense\"</span><span style=\"color:#E1E4E8\">&gt;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    &lt;</span><span style=\"color:#85E89D\">ion-toolbar</span><span style=\"color:#B392F0\"> color</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"light\"</span><span style=\"color:#E1E4E8\">&gt;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">      &lt;</span><span style=\"color:#85E89D\">ion-title</span><span style=\"color:#B392F0\"> size</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"large\"</span><span style=\"color:#E1E4E8\">&gt;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">        Settings</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">      &lt;/</span><span style=\"color:#85E89D\">ion-title</span><span style=\"color:#E1E4E8\">&gt;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    &lt;/</span><span style=\"color:#85E89D\">ion-toolbar</span><span style=\"color:#E1E4E8\">&gt;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  &lt;/</span><span style=\"color:#85E89D\">ion-header</span><span style=\"color:#E1E4E8\">&gt;</span></span>\n<span class=\"line\"></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  &lt;</span><span style=\"color:#85E89D\">ion-list</span><span style=\"color:#B392F0\"> inset</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"true\"</span><span style=\"color:#E1E4E8\">&gt;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    &lt;</span><span style=\"color:#85E89D\">ion-item-group</span><span style=\"color:#E1E4E8\">&gt;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">      &lt;</span><span style=\"color:#85E89D\">ion-item</span><span style=\"color:#B392F0\"> detail</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"true\"</span><span style=\"color:#B392F0\"> routerLink</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"/main/settings/account\"</span><span style=\"color:#E1E4E8\">&gt;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">        &lt;</span><span style=\"color:#85E89D\">ion-icon</span><span style=\"color:#B392F0\"> name</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"person-circle-outline\"</span><span style=\"color:#B392F0\"> slot</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"start\"</span><span style=\"color:#B392F0\"> size</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"small\"</span><span style=\"color:#B392F0\"> class</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"menu-icon color-primary\"</span><span style=\"color:#E1E4E8\">&gt;&lt;/</span><span style=\"color:#85E89D\">ion-icon</span><span style=\"color:#E1E4E8\">&gt;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">        &lt;</span><span style=\"color:#85E89D\">ion-label</span><span style=\"color:#B392F0\"> i18n</span><span style=\"color:#E1E4E8\">&gt;Account&lt;/</span><span style=\"color:#85E89D\">ion-label</span><span style=\"color:#E1E4E8\">&gt;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">      &lt;/</span><span style=\"color:#85E89D\">ion-item</span><span style=\"color:#E1E4E8\">&gt;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">      &lt;</span><span style=\"color:#85E89D\">ion-item</span><span style=\"color:#B392F0\"> detail</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"true\"</span><span style=\"color:#B392F0\"> routerLink</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"/main/settings/printer\"</span><span style=\"color:#E1E4E8\">&gt;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">        &lt;</span><span style=\"color:#85E89D\">ion-icon</span><span style=\"color:#B392F0\"> name</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"print-outline\"</span><span style=\"color:#B392F0\"> slot</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"start\"</span><span style=\"color:#B392F0\"> size</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"small\"</span><span style=\"color:#B392F0\"> class</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"menu-icon color-tertiary\"</span><span style=\"color:#E1E4E8\">&gt;&lt;/</span><span style=\"color:#85E89D\">ion-icon</span><span style=\"color:#E1E4E8\">&gt;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">        &lt;</span><span style=\"color:#85E89D\">ion-label</span><span style=\"color:#B392F0\"> i18n</span><span style=\"color:#E1E4E8\">&gt;Printer&lt;/</span><span style=\"color:#85E89D\">ion-label</span><span style=\"color:#E1E4E8\">&gt;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">      &lt;/</span><span style=\"color:#85E89D\">ion-item</span><span style=\"color:#E1E4E8\">&gt;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">      &lt;</span><span style=\"color:#85E89D\">ion-item</span><span style=\"color:#E1E4E8\">&gt;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">        &lt;</span><span style=\"color:#85E89D\">ion-icon</span><span style=\"color:#B392F0\"> slot</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"start\"</span><span style=\"color:#B392F0\"> size</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"small\"</span><span style=\"color:#B392F0\"> class</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"menu-icon color-warning\"</span><span style=\"color:#B392F0\"> name</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"moon\"</span><span style=\"color:#E1E4E8\">&gt;&lt;/</span><span style=\"color:#85E89D\">ion-icon</span><span style=\"color:#E1E4E8\">&gt;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">        &lt;</span><span style=\"color:#85E89D\">ion-toggle</span><span style=\"color:#B392F0\"> [(ngModel)]</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"isDark\"</span><span style=\"color:#B392F0\"> (ionChange)</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"vm.changeTheme(isDark())\"</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">        &gt;&lt;</span><span style=\"color:#85E89D\">ng-container</span><span style=\"color:#B392F0\"> i18n</span><span style=\"color:#E1E4E8\">&gt;Use dark mode&lt;/</span><span style=\"color:#85E89D\">ng-container</span><span style=\"color:#E1E4E8\">&gt;&lt;/</span><span style=\"color:#85E89D\">ion-toggle</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">        &gt;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">      &lt;/</span><span style=\"color:#85E89D\">ion-item</span><span style=\"color:#E1E4E8\">&gt;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    &lt;/</span><span style=\"color:#85E89D\">ion-item-group</span><span style=\"color:#E1E4E8\">&gt;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  &lt;/</span><span style=\"color:#85E89D\">ion-list</span><span style=\"color:#E1E4E8\">&gt;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">&lt;/</span><span style=\"color:#85E89D\">ion-content</span><span style=\"color:#E1E4E8\">&gt;</span></span>\n<span class=\"line\"></span></code></pre></div><p data-line=\"54\" class=\"code-line\">With only this template, you should see something like this:</p>\n<p data-line=\"56\" class=\"code-line\"><img src=\"/images/5325127b665d56/step-1.png\" alt=\"step-1.png\" class=\"md-img\" loading=\"lazy\"></p>\n<h2 id=\"step-2%3A-style-the-icons\" data-line=\"59\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#step-2%3A-style-the-icons\" aria-hidden=\"true\"></a> Step 2: Style the icons</h2>\n<p data-line=\"61\" class=\"code-line\">Next, style the icons. If the parent is always <code>ion-list[inset=true]</code> and icons are always <code>ion-item ion-icon[slot=start]</code>, the <code>menu-icon</code> class is optional. Here I keep <code>menu-icon</code> for reuse and add color classes. Colors come from Ionic theme variables, but fixed values work too.</p>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"63\"><span class=\"line\"><span style=\"color:#79B8FF\">ion-icon.menu-icon</span><span style=\"color:#E1E4E8\"> {</span></span>\n<span class=\"line\"><span style=\"color:#79B8FF\">  border-radius</span><span style=\"color:#E1E4E8\">: </span><span style=\"color:#79B8FF\">4</span><span style=\"color:#F97583\">px</span><span style=\"color:#E1E4E8\">;</span></span>\n<span class=\"line\"><span style=\"color:#79B8FF\">  padding</span><span style=\"color:#E1E4E8\">: </span><span style=\"color:#79B8FF\">3</span><span style=\"color:#F97583\">px</span><span style=\"color:#E1E4E8\">;</span></span>\n<span class=\"line\"></span>\n<span class=\"line\"><span style=\"color:#85E89D\">  &amp;</span><span style=\"color:#B392F0\">.color-primary</span><span style=\"color:#E1E4E8\"> {</span></span>\n<span class=\"line\"><span style=\"color:#79B8FF\">    background-color</span><span style=\"color:#E1E4E8\">: </span><span style=\"color:#B392F0\">var(</span><span style=\"color:#FFAB70\">--ion-color-primary</span><span style=\"color:#B392F0\">)</span><span style=\"color:#E1E4E8\">;</span></span>\n<span class=\"line\"><span style=\"color:#79B8FF\">    color</span><span style=\"color:#E1E4E8\">: </span><span style=\"color:#B392F0\">var(</span><span style=\"color:#FFAB70\">--ion-color-primary-contrast</span><span style=\"color:#B392F0\">)</span><span style=\"color:#E1E4E8\">;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  }</span></span>\n<span class=\"line\"></span>\n<span class=\"line\"><span style=\"color:#85E89D\">  &amp;</span><span style=\"color:#B392F0\">.color-secondary</span><span style=\"color:#E1E4E8\"> {</span></span>\n<span class=\"line\"><span style=\"color:#79B8FF\">    background-color</span><span style=\"color:#E1E4E8\">: </span><span style=\"color:#B392F0\">var(</span><span style=\"color:#FFAB70\">--ion-color-secondary-shade</span><span style=\"color:#B392F0\">)</span><span style=\"color:#E1E4E8\">;</span></span>\n<span class=\"line\"><span style=\"color:#79B8FF\">    color</span><span style=\"color:#E1E4E8\">: </span><span style=\"color:#B392F0\">var(</span><span style=\"color:#FFAB70\">--ion-color-secondary-contrast</span><span style=\"color:#B392F0\">)</span><span style=\"color:#E1E4E8\">;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  }</span></span>\n<span class=\"line\"></span>\n<span class=\"line\"><span style=\"color:#85E89D\">  &amp;</span><span style=\"color:#B392F0\">.color-tertiary</span><span style=\"color:#E1E4E8\"> {</span></span>\n<span class=\"line\"><span style=\"color:#79B8FF\">    background-color</span><span style=\"color:#E1E4E8\">: </span><span style=\"color:#B392F0\">var(</span><span style=\"color:#FFAB70\">--ion-color-tertiary</span><span style=\"color:#B392F0\">)</span><span style=\"color:#E1E4E8\">;</span></span>\n<span class=\"line\"><span style=\"color:#79B8FF\">    color</span><span style=\"color:#E1E4E8\">: </span><span style=\"color:#B392F0\">var(</span><span style=\"color:#FFAB70\">--ion-color-tertiary-contrast</span><span style=\"color:#B392F0\">)</span><span style=\"color:#E1E4E8\">;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  }</span></span>\n<span class=\"line\"></span>\n<span class=\"line\"><span style=\"color:#85E89D\">  &amp;</span><span style=\"color:#B392F0\">.color-success</span><span style=\"color:#E1E4E8\"> {</span></span>\n<span class=\"line\"><span style=\"color:#79B8FF\">    background-color</span><span style=\"color:#E1E4E8\">: </span><span style=\"color:#B392F0\">var(</span><span style=\"color:#FFAB70\">--ion-color-success-shade</span><span style=\"color:#B392F0\">)</span><span style=\"color:#E1E4E8\">;</span></span>\n<span class=\"line\"><span style=\"color:#79B8FF\">    color</span><span style=\"color:#E1E4E8\">: </span><span style=\"color:#B392F0\">var(</span><span style=\"color:#FFAB70\">--ion-color-success-contrast</span><span style=\"color:#B392F0\">)</span><span style=\"color:#E1E4E8\">;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  }</span></span>\n<span class=\"line\"></span>\n<span class=\"line\"><span style=\"color:#85E89D\">  &amp;</span><span style=\"color:#B392F0\">.color-warning</span><span style=\"color:#E1E4E8\"> {</span></span>\n<span class=\"line\"><span style=\"color:#79B8FF\">    background-color</span><span style=\"color:#E1E4E8\">: </span><span style=\"color:#B392F0\">var(</span><span style=\"color:#FFAB70\">--ion-color-warning</span><span style=\"color:#B392F0\">)</span><span style=\"color:#E1E4E8\">;</span></span>\n<span class=\"line\"><span style=\"color:#79B8FF\">    color</span><span style=\"color:#E1E4E8\">: </span><span style=\"color:#B392F0\">var(</span><span style=\"color:#FFAB70\">--ion-color-warning-contrast</span><span style=\"color:#B392F0\">)</span><span style=\"color:#E1E4E8\">;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  }</span></span>\n<span class=\"line\"></span>\n<span class=\"line\"><span style=\"color:#85E89D\">  &amp;</span><span style=\"color:#B392F0\">.color-danger</span><span style=\"color:#E1E4E8\"> {</span></span>\n<span class=\"line\"><span style=\"color:#79B8FF\">    background-color</span><span style=\"color:#E1E4E8\">: </span><span style=\"color:#B392F0\">var(</span><span style=\"color:#FFAB70\">--ion-color-danger</span><span style=\"color:#B392F0\">)</span><span style=\"color:#E1E4E8\">;</span></span>\n<span class=\"line\"><span style=\"color:#79B8FF\">    color</span><span style=\"color:#E1E4E8\">: </span><span style=\"color:#B392F0\">var(</span><span style=\"color:#FFAB70\">--ion-color-danger-contrast</span><span style=\"color:#B392F0\">)</span><span style=\"color:#E1E4E8\">;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  }</span></span>\n<span class=\"line\"></span>\n<span class=\"line\"><span style=\"color:#85E89D\">  &amp;</span><span style=\"color:#B392F0\">.color-medium</span><span style=\"color:#E1E4E8\"> {</span></span>\n<span class=\"line\"><span style=\"color:#79B8FF\">    background-color</span><span style=\"color:#E1E4E8\">: </span><span style=\"color:#B392F0\">var(</span><span style=\"color:#FFAB70\">--ion-color-medium</span><span style=\"color:#B392F0\">)</span><span style=\"color:#E1E4E8\">;</span></span>\n<span class=\"line\"><span style=\"color:#79B8FF\">    color</span><span style=\"color:#E1E4E8\">: </span><span style=\"color:#B392F0\">var(</span><span style=\"color:#FFAB70\">--ion-color-medium-contrast</span><span style=\"color:#B392F0\">)</span><span style=\"color:#E1E4E8\">;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  }</span></span>\n<span class=\"line\"></span>\n<span class=\"line\"><span style=\"color:#85E89D\">  &amp;</span><span style=\"color:#B392F0\">.color-light</span><span style=\"color:#E1E4E8\"> {</span></span>\n<span class=\"line\"><span style=\"color:#79B8FF\">    background-color</span><span style=\"color:#E1E4E8\">: </span><span style=\"color:#B392F0\">var(</span><span style=\"color:#FFAB70\">--ion-color-light</span><span style=\"color:#B392F0\">)</span><span style=\"color:#E1E4E8\">;</span></span>\n<span class=\"line\"><span style=\"color:#79B8FF\">    color</span><span style=\"color:#E1E4E8\">: </span><span style=\"color:#B392F0\">var(</span><span style=\"color:#FFAB70\">--ion-color-light-contrast</span><span style=\"color:#B392F0\">)</span><span style=\"color:#E1E4E8\">;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  }</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">}</span></span>\n<span class=\"line\"></span></code></pre></div><p data-line=\"110\" class=\"code-line\">That gives you styled icons quickly.</p>\n<p data-line=\"112\" class=\"code-line\"><img src=\"/images/5325127b665d56/step-2.png\" alt=\"step-2.png\" class=\"md-img\" loading=\"lazy\"></p>\n<h2 id=\"step-3%3A-style-the-list\" data-line=\"114\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#step-3%3A-style-the-list\" aria-hidden=\"true\"></a> Step 3: Style the list</h2>\n<p data-line=\"116\" class=\"code-line\">Finally, style the list. The main default issue is that <code>ion-list[inset=true]</code> has a background color. If you add titles or notes, they render inside that colored DOM. So make <code>ion-list[inset=true]</code> transparent and move the background to <code>ion-item-group</code>.</p>\n<p data-line=\"118\" class=\"code-line\">On iOS, items are rounded; Material Design is not, so <code>border-radius</code> applies only to <code>ion-item-group.ios</code>. Item dividers hide on the last item in a group (<code>ion-item-group &gt; :is(ion-item):last-child</code>).</p>\n<p data-line=\"120\" class=\"code-line\">Nothing too exotic—if you read CSS, this should look familiar.</p>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"122\"><span class=\"line\"><span style=\"color:#79B8FF\">ion-content</span><span style=\"color:#B392F0\">[color=light]</span><span style=\"color:#E1E4E8\"> {</span></span>\n<span class=\"line\"><span style=\"color:#79B8FF\">  ion-list</span><span style=\"color:#B392F0\">[inset=true]</span><span style=\"color:#E1E4E8\"> {</span></span>\n<span class=\"line\"><span style=\"color:#85E89D\">    &amp;</span><span style=\"color:#B392F0\">.list-inset</span><span style=\"color:#E1E4E8\"> {</span></span>\n<span class=\"line\"><span style=\"color:#79B8FF\">      background</span><span style=\"color:#E1E4E8\">: </span><span style=\"color:#79B8FF\">transparent</span><span style=\"color:#E1E4E8\">;</span></span>\n<span class=\"line\"></span>\n<span class=\"line\"><span style=\"color:#79B8FF\">      ion-list-header</span><span style=\"color:#E1E4E8\"> {</span></span>\n<span class=\"line\"><span style=\"color:#79B8FF\">        ion-label</span><span style=\"color:#E1E4E8\"> {</span></span>\n<span class=\"line\"><span style=\"color:#79B8FF\">          font-size</span><span style=\"color:#E1E4E8\">: </span><span style=\"color:#79B8FF\">0.9</span><span style=\"color:#F97583\">rem</span><span style=\"color:#E1E4E8\">;</span></span>\n<span class=\"line\"><span style=\"color:#79B8FF\">          font-weight</span><span style=\"color:#E1E4E8\">: </span><span style=\"color:#79B8FF\">normal</span><span style=\"color:#E1E4E8\">;</span></span>\n<span class=\"line\"><span style=\"color:#79B8FF\">          margin</span><span style=\"color:#E1E4E8\">: </span><span style=\"color:#79B8FF\">8</span><span style=\"color:#F97583\">px</span><span style=\"color:#79B8FF\"> 0</span><span style=\"color:#79B8FF\"> 4</span><span style=\"color:#F97583\">px</span><span style=\"color:#E1E4E8\">;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">        }</span></span>\n<span class=\"line\"><span style=\"color:#79B8FF\">        ion-note</span><span style=\"color:#E1E4E8\"> {</span></span>\n<span class=\"line\"><span style=\"color:#79B8FF\">          font-size</span><span style=\"color:#E1E4E8\">: </span><span style=\"color:#79B8FF\">0.9</span><span style=\"color:#F97583\">rem</span><span style=\"color:#E1E4E8\">;</span></span>\n<span class=\"line\"><span style=\"color:#79B8FF\">          margin</span><span style=\"color:#E1E4E8\">: </span><span style=\"color:#79B8FF\">8</span><span style=\"color:#F97583\">px</span><span style=\"color:#79B8FF\"> 16</span><span style=\"color:#F97583\">px</span><span style=\"color:#79B8FF\"> 4</span><span style=\"color:#F97583\">px</span><span style=\"color:#79B8FF\"> 0</span><span style=\"color:#E1E4E8\">;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">        }</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">      }</span></span>\n<span class=\"line\"></span>\n<span class=\"line\"><span style=\"color:#79B8FF\">      ion-item-group.ios</span><span style=\"color:#E1E4E8\"> {</span></span>\n<span class=\"line\"><span style=\"color:#79B8FF\">        border-radius</span><span style=\"color:#E1E4E8\">: </span><span style=\"color:#79B8FF\">10</span><span style=\"color:#F97583\">px</span><span style=\"color:#E1E4E8\">;</span></span>\n<span class=\"line\"><span style=\"color:#79B8FF\">        overflow</span><span style=\"color:#E1E4E8\">: </span><span style=\"color:#79B8FF\">hidden</span><span style=\"color:#E1E4E8\">;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">      }</span></span>\n<span class=\"line\"></span>\n<span class=\"line\"><span style=\"color:#79B8FF\">      ion-item-group</span><span style=\"color:#F97583\"> &gt;</span><span style=\"color:#E1E4E8\"> :</span><span style=\"color:#B392F0\">is(</span><span style=\"color:#79B8FF\">ion-item</span><span style=\"color:#B392F0\">)</span><span style=\"color:#E1E4E8\">:</span><span style=\"color:#79B8FF\">last-child </span><span style=\"color:#E1E4E8\">{</span></span>\n<span class=\"line\"><span style=\"color:#79B8FF\">        --border-width</span><span style=\"color:#E1E4E8\">: </span><span style=\"color:#79B8FF\">0</span><span style=\"color:#F97583\">px</span><span style=\"color:#F97583\"> !important</span><span style=\"color:#E1E4E8\">;</span></span>\n<span class=\"line\"><span style=\"color:#79B8FF\">        --show-full-highlight</span><span style=\"color:#E1E4E8\">: </span><span style=\"color:#79B8FF\">0</span><span style=\"color:#F97583\"> !important</span><span style=\"color:#E1E4E8\">;</span></span>\n<span class=\"line\"><span style=\"color:#79B8FF\">        --inner-border-width</span><span style=\"color:#E1E4E8\">: </span><span style=\"color:#79B8FF\">0</span><span style=\"color:#F97583\">px</span><span style=\"color:#F97583\"> !important</span><span style=\"color:#E1E4E8\">;</span></span>\n<span class=\"line\"><span style=\"color:#79B8FF\">        --show-inset-highlight</span><span style=\"color:#E1E4E8\">: </span><span style=\"color:#79B8FF\">0</span><span style=\"color:#F97583\"> !important</span><span style=\"color:#E1E4E8\">;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">      }</span></span>\n<span class=\"line\"></span>\n<span class=\"line\"><span style=\"color:#85E89D\">      &amp;</span><span style=\"color:#F97583\"> &gt;</span><span style=\"color:#79B8FF\"> ion-note</span><span style=\"color:#E1E4E8\"> {</span></span>\n<span class=\"line\"><span style=\"color:#79B8FF\">        color</span><span style=\"color:#E1E4E8\">: </span><span style=\"color:#B392F0\">var(</span><span style=\"color:#FFAB70\">--ion-color-medium-tint</span><span style=\"color:#B392F0\">)</span><span style=\"color:#E1E4E8\">;</span></span>\n<span class=\"line\"><span style=\"color:#79B8FF\">        font-size</span><span style=\"color:#E1E4E8\">: </span><span style=\"color:#79B8FF\">0.9</span><span style=\"color:#F97583\">rem</span><span style=\"color:#E1E4E8\">;</span></span>\n<span class=\"line\"><span style=\"color:#79B8FF\">        display</span><span style=\"color:#E1E4E8\">: </span><span style=\"color:#79B8FF\">block</span><span style=\"color:#E1E4E8\">;</span></span>\n<span class=\"line\"><span style=\"color:#79B8FF\">        margin</span><span style=\"color:#E1E4E8\">: </span><span style=\"color:#79B8FF\">8</span><span style=\"color:#F97583\">px</span><span style=\"color:#79B8FF\"> 16</span><span style=\"color:#F97583\">px</span><span style=\"color:#E1E4E8\">;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">      }</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    }</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  }</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">}</span></span>\n<span class=\"line\"></span></code></pre></div><p data-line=\"163\" class=\"code-line\">The finished layout:</p>\n<p data-line=\"165\" class=\"code-line\"><img src=\"/images/5325127b665d56/step-3.png\" alt=\"step-3.png\" class=\"md-img\" loading=\"lazy\"></p>\n<h2 id=\"summary\" data-line=\"167\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#summary\" aria-hidden=\"true\"></a> Summary</h2>\n<p data-line=\"169\" class=\"code-line\">Ionic provides push transitions and navigation stacks—hard to implement performantly on the web. For backward compatibility it does not ship every small design tweak as a component, but with a solid base you can reach the design you want with CSS like this.</p>\n<p data-line=\"171\" class=\"code-line\"><img src=\"/images/5325127b665d56/last.png\" alt=\"last.png\" class=\"md-img\" loading=\"lazy\"></p>\n<p data-line=\"173\" class=\"code-line\">Split what the UI framework must own from what you can implement yourself, and you can design more efficiently.</p>\n<p data-line=\"175\" class=\"code-line\">See you next time.</p>\n","headings":[{"id":"step-1%3A-set-up-the-html","text":"Step 1: Set up the HTML","level":2},{"id":"step-2%3A-style-the-icons","text":"Step 2: Style the icons","level":2},{"id":"step-3%3A-style-the-list","text":"Step 3: Style the list","level":2},{"id":"summary","text":"Summary","level":2}]} as const;
